@Override
    public void readFromNbt(NbtCompound tag) {
        this.riftRecordUuids.clear();
        for (NbtElement uuid : tag.getList("rift_records", NbtElement.INT_ARRAY_TYPE)) {
            this.riftRecordUuids.add(NbtHelper.toUuid(uuid));
        }
    }

